class RunCursor:
    def __init__(self, nums):
        # Drain the whole stream into a list of runs up front.
        self.runs = []
        while nums.hasNext():
            x = nums.next()
            if self.runs and self.runs[-1][0] == x:
                self.runs[-1][1] += 1
            else:
                self.runs.append([x, 1])
        self.i = 0

    def next(self) -> list[int]:
        if self.i == len(self.runs):
            return []
        self.i += 1
        return list(self.runs[self.i - 1])

    def peek(self) -> list[int]:
        return list(self.runs[self.i]) if self.i < len(self.runs) else []

    def hasNext(self) -> bool:
        return self.i < len(self.runs)

    def skip(self, k: int) -> int:
        n = min(k, len(self.runs) - self.i)
        self.i += n
        return n

