struct RunCursor {
    runs: Vec<Vec<i32>>,
    i: usize,
}

impl RunCursor {
    fn new(nums: IntIter) -> Self {
        // Drain the whole stream into a list of runs up front.
        let mut runs: Vec<Vec<i32>> = Vec::new();
        for x in nums {
            match runs.last_mut() {
                Some(r) if r[0] == x => r[1] += 1,
                _ => runs.push(vec![x, 1]),
            }
        }
        RunCursor { runs, i: 0 }
    }

    fn next(&mut self) -> Vec<i32> {
        if self.i == self.runs.len() {
            return vec![];
        }
        self.i += 1;
        self.runs[self.i - 1].clone()
    }

    fn peek(&mut self) -> Vec<i32> {
        self.runs.get(self.i).cloned().unwrap_or_default()
    }

    fn has_next(&self) -> bool {
        self.i < self.runs.len()
    }

    fn skip(&mut self, k: i32) -> i32 {
        let n = (k as usize).min(self.runs.len() - self.i);
        self.i += n;
        n as i32
    }
}

