class RunCursor:
    def __init__(self, nums):
        self.it = nums
        self.buf = None    # the next run as [value, length], read but not yet handed out
        self.carry = None  # the first value of the run after it, already read off the stream

    def _load(self):
        if self.buf is not None:
            return
        if self.carry is not None:
            value, self.carry = self.carry, None
        elif self.it.hasNext():
            value = self.it.next()
        else:
            return
        length = 1
        while self.it.hasNext():
            x = self.it.next()
            if x != value:
                self.carry = x  # one past the run: can't un-read it, so keep it
                break
            length += 1
        self.buf = [value, length]

    def next(self) -> list[int]:
        self._load()
        run, self.buf = self.buf, None
        return run if run is not None else []

    def peek(self) -> list[int]:
        self._load()
        return list(self.buf) if self.buf is not None else []

    def hasNext(self) -> bool:
        return self.buf is not None or self.carry is not None or self.it.hasNext()

    def skip(self, k: int) -> int:
        skipped = 0
        while skipped < k:
            self._load()
            if self.buf is None:
                break
            self.buf = None
            skipped += 1
        return skipped

