struct RunCursor {
    it: IntIter,
    buf: Option<(i32, i32)>, // the next run (value, length), read but not yet handed out
    carry: Option<i32>,      // the first value of the run after it, already read off the stream
}

impl RunCursor {
    fn new(nums: IntIter) -> Self {
        RunCursor { it: nums, buf: None, carry: None }
    }

    fn load(&mut self) {
        if self.buf.is_some() {
            return;
        }
        let value = match self.carry.take() {
            Some(v) => v,
            None => match self.it.next() {
                Some(v) => v,
                None => return,
            },
        };
        let mut length = 1;
        while let Some(x) = self.it.next() {
            if x != value {
                self.carry = Some(x); // one past the run: can't un-read it, so keep it
                break;
            }
            length += 1;
        }
        self.buf = Some((value, length));
    }

    fn next(&mut self) -> Vec<i32> {
        self.load();
        match self.buf.take() {
            Some((v, c)) => vec![v, c],
            None => vec![],
        }
    }

    fn peek(&mut self) -> Vec<i32> {
        self.load();
        match self.buf {
            Some((v, c)) => vec![v, c],
            None => vec![],
        }
    }

    fn has_next(&self) -> bool {
        // IntIter is an ExactSizeIterator: len() is what's left unread.
        self.buf.is_some() || self.carry.is_some() || self.it.len() > 0
    }

    fn skip(&mut self, k: i32) -> i32 {
        let mut skipped = 0;
        while skipped < k {
            self.load();
            if self.buf.take().is_none() {
                break;
            }
            skipped += 1;
        }
        skipped
    }
}
